    comb = [[0] * (k+1) for _ in range(n+1)]
    for i in range(n+1):
        comb[i][0] = 1
        for j in range(1, min(i, k)+1):
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD

    def compute_sum(arr):
        """计算排序后数组arr的所有k元子集的极差之和，模MOD"""
        total = 0
        for i in range(n):
            for j in range(i+1, n):
                diff = arr[j] - arr[i]
                cnt = comb[j - i - 1][k - 2] if k >= 2 else 1
                total = (total + diff * cnt) % MOD
        return total

    # 检查初始状态
    if compute_sum(a_sorted) == S:
        return '0'

    # 构建候选值集合：在原容量附近微调，认为不需要大幅度改动
    candidate = set()
