    if n > 20:
        # 大规模数据，使用近似：公平度之和 ≈ 所有两两差的绝对值之和（即假设k=2的情况）
        def beauty_sum(arr):
            arr = sorted(arr)
            total = 0
            m = len(arr)
            for i in range(m):
                for j in range(i+1, m):
                    total += arr[j] - arr[i]
            return total
    else:
