  "constraints": [
    "时间限制：2.0 秒",
    "内存限制：256 MB",
    "1 ≤ n ≤ 2000",
    "0 ≤ t_i ≤ 2000",
    "1 ≤ c_i ≤ 10^9",
    "总费用可能超过 32 位整数范围，请使用 64 位整数。"
