messages.content:
请在当前规则集中选择最适合当前 schema 的规则。
要求：
- 目标是在保证可落地的前提下，让生成题的创新度和难度尽可能高。
- 如果某条规则只会导致浅改、换皮、后处理增强或伪融合，不要选择它。
- `selection_reason` 要直接说明为什么它优于其余规则。
- 优先返回 `ranked_rule_ids`，按推荐尝试顺序排列前 2 到 3 条规则；`selected_rule_id` 保留为第一推荐项。
- `innovation_reason` 要说明它会把哪些核心义务拉离原题。
- `difficulty_reason` 要说明它会在哪个主求解责任上抬高难度。
- `risk_reason` 要说明主要风险；如果风险可控，也要明确写出来。
- 如果提供了 `revision_context`，要优先修复其中涉及规则选择、结构差异和反换皮风险的问题，并保留 `strengths_to_keep`。
- 若 `revision_context` 包含 `revision_history` 或 `revision_summary`，必须综合此前所有轮次的有用信息，不要只依据最近一轮的修订建议。
- 如果没有规则满足条件，返回失败状态，不要勉强挑选。

{
  "mode": "single_seed_extension",
  "available_rules": [
    {
      "id": "canonical_witness",
      "family": "output_upgrade",
      "audit_tags": [
        "single_seed",
        "witness",
        "output_contract"
      ],
      "handler": "canonical_witness",
      "enabled": true,
      "summary": "把原题改成需要输出并校验一个规范解的新题。",
      "eligibility": {
        "required_seed_properties": [
          "原题本身有明确的解对象，或者答案可以恢复成方案",
          "方案有自然顺序，或者能定义清楚的规范"
        ],
        "forbidden_seed_properties": [
          "原题本来就要求输出完整方案",
          "原解只要顺手回溯就能拿到方案"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "C",
          "O",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "canonical_witness",
        "target_shift": "从给答案改成给规范解",
        "new_obligation": "输出一个可以直接检查的规范方案"
      },
      "helpers": [
        {
          "id": "canonical_order_pressure",
          "summary": "把规范顺序推进到主状态演化。",
          "must_realize_in": [
            "core_constraints",
            "objective",
            "invariant"
          ],
          "target_axes": [
            "C",
            "O",
            "V"
          ],
          "innovation_role": "让输出对象与验证责任离开原题路径。",
          "difficulty_role": "让状态转移承担新的规范性证明。",
          "prompt_guidance": [
            "让规范顺序进入合法性或最优性定义。",
            "让验证责任依赖全局结构。"
          ],
          "redlines": [
            "不能退化为输出后处理。",
            "不能只加字典序描述。"
          ]
        },
        {
          "id": "proof_bearing_output",
          "summary": "把输出对象升级成带证明责任的规范解。",
          "must_realize_in": [
            "objective",
            "invariant"
          ],
          "target_axes": [
            "O",
            "V"
          ],
          "innovation_role": "让新题输出责任变成可校验的解对象。",
          "difficulty_role": "要求解法解释为什么规范解满足全局约束。",
          "prompt_guidance": [
            "让输出对象直接承接新校验责任。",
            "不要把证明责任留在题面备注之外。"
          ],
          "redlines": [
            "不能把规范性留给说明文补充。",
            "不能只要求输出任意方案。"
          ]
        },
        {
          "id": "constraint_reweighting",
          "summary": "重排主约束优先级，让规范解要求进入主约束。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "让规范性要求进入主约束的优先级分配。",
          "difficulty_role": "迫使解法在状态设计里处理新的约束主次关系。",
          "prompt_guidance": [
            "让规范要求改变主约束的优先级组织。",
            "让不变量反映新的约束主次关系。"
          ],
          "redlines": [
            "不能只增加一句格式要求。",
            "不能保持原主约束完全不动。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "输出要求必须真正变了",
          "规范要求要影响主要解法",
          "规定必须变化的轴都要真的变化"
        ]
      },
      "examples": {
        "positive": "把是否可行改成输出字典序最小的合法构造。",
        "negative": "原题先求值，再顺手回溯一个任意方案。"
      },
      "failure_templates": {
        "not_applicable": "这道种子题缺少适合做规范化的解对象，不适合扩成规范解题。",
        "difference_insufficient": "加上规范解输出之后，主要解法几乎没变，还是表面修改。"
      },
      "planner_output_contract": {
        "required_fields": [
          "eligibility_reason",
          "core_transformation_summary",
          "difference_plan",
          "new_schema",
          "algorithmic_delta_claim",
          "anti_shallow_rationale",
          "applied_helpers"
        ]
      }
    },
    {
      "id": "existence_to_counting",
      "family": "objective_upgrade",
      "audit_tags": [
        "single_seed",
        "counting",
        "deduplication"
      ],
      "handler": "existence_to_counting",
      "enabled": true,
      "summary": "把存在性或单一最优值问题改成一个对象明确、去重规则明确的计数题。",
      "eligibility": {
        "required_seed_properties": [
          "解空间有限",
          "不同解之间的等价关系能说清楚",
          "可以按某种单元拆分并汇总"
        ],
        "forbidden_seed_properties": [
          "解空间天然无限",
          "去重规则说不清楚"
        ]
      },
      "required_axis_changes": {
        "must_change": [
          "O",
          "C",
          "V"
        ]
      },
      "core_transformation": {
        "primary_operator": "existence_to_counting",
        "target_shift": "从存在性或最优值改成计数",
        "new_obligation": "定义清楚计数对象、有限性和去重规则"
      },
      "helpers": [
        {
          "id": "counting_unit_definition",
          "summary": "明确计数对象、等价关系与不同答案口径。",
          "must_realize_in": [
            "core_constraints",
            "objective",
            "invariant"
          ],
          "target_axes": [
            "C",
            "O",
            "V"
          ],
          "innovation_role": "把原题答案换成对象明确的计数结果。",
          "difficulty_role": "要求解法处理等价类和有限性证明。",
          "prompt_guidance": [
            "把计数对象直接写进目标定义。",
            "把去重口径写进约束或不变量。"
          ],
          "redlines": [
            "不能只补一个模数。",
            "不能不定义什么算不同答案。"
          ]
        },
        {
          "id": "state_factorization",
          "summary": "把解空间拆成可汇总的计数单元。",
          "must_realize_in": [
            "core_constraints",
            "invariant"
          ],
          "target_axes": [
            "C",
            "V"
          ],
          "innovation_role": "让计数从主状态组织方式中自然长出来。",
          "difficulty_role": "要求解法在分解与汇总层面重建主状态。",
          "prompt_guidance": [
            "让核心约束说明如何拆成计数单元。",
            "让不变量解释单元之间如何避免重复。"
          ],
          "redlines": [
            "不能保持原状态结构不动。",
            "不能把计数只当成结果后处理。"
          ]
        },
        {
          "id": "counting_obligation_lock",
          "summary": "把计数责任锁进主求解目标而不是附带统计。",
          "must_realize_in": [
            "core_constraints",
            "objective"
          ],
          "target_axes": [
            "C",
            "O"
          ],
          "innovation_role": "把原题主目标替换成新的计数义务。",
          "difficulty_role": "要求算法同时承担计数正确性和去重正确性。",
          "prompt_guidance": [
            "让目标定义主导状态转移。",
            "不要保留原判定主目标再顺手计数。"
          ],
          "redlines": [
            "不能继续由原题判定过程主导。",
            "不能把计数目标放进备注。"
          ]
        }
      ],
      "validation_contract": {
        "hard_checks": [
          "必须说明什么样的解算不同",
          "必须说明为什么可数，或者说明取模方式",
          "必须说明按什么单元拆分和汇总"
        ]
      },
