          },
          "value_range": {
            "min": 1,
            "max": 1000000000
          },
          "properties": {}
        }
      ]
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "original_coverage_after_modifications",
          "description": "After modifications, there must exist a subset P of items so that if you pay to organize them, the total time spent (ti) is at least the number of items you can steal (i.e., n - |P|). Formally, ∑_{i∈P} ti ≥ n - |P|.",
          "formal": "∃ P ⊆ {1..n} : ∑_{i∈P} ti ≥ n - |P|",
          "source_sections": [
            "derived from original problem"
          ]
        },
        {
          "name": "allowed_modifications",
          "description": "For each item i, you may change its space ti to any non‑negative integer and its cost ci to any positive integer. The cost of modifying item i is |new_ti - old_ti| + |new_ci - old_ci|. The total modification cost is the sum over all items.",
          "formal": "Let Δt_i = new_ti - ti, Δc_i = new_ci - ci. Modification cost = ∑_{i=1..n} (|Δt_i| + |Δc_i|). All new_ti ≥ 0, new_ci ≥ 1.",
          "source_sections": [
            "constructed"
          ]
        },
        {
          "name": "target_minimum_payment_condition",
          "description": "The modified item set must satisfy: its minimum possible total organization cost (i.e., the optimal payment over all valid subsets P) is exactly K. That is, min_{P : ∑ti ≥ n - |P|} ∑_{i∈P} ci = K.",
          "formal": "min_pay = min_{P : ∑ti ≥ n - |P|} ∑_{i∈P} ci == K",
          "source_sections": [
            "constructed"
          ]
        }
      ]
    },
    "objective": {
      "type": "inverse_design_with_target",
      "description": "Minimize the total modification cost under the condition that the modified item set achieves target minimum payment K. Output the minimum modification cost; if impossible, output -1. Additionally, if feasible, output one optimal modification scheme (new values of ti and ci for each item).",
      "target": "optimal_modification_scheme",
      "requires_solution": true
    },
    "invariant": {
      "invariants": [
        {
          "name": "modification_dp_optimality",
          "description": "During the algorithm, a dynamic programming state tracks (prefix of items, coverage volume, total payment) and the minimal modification cost to achieve it. The invariant guarantees that the found modification scheme makes the minimum payment exactly K, and no other modification with lower total cost can achieve the same. The DP optimal substructure is maintained by considering each possible combination of modification choices for each item and updating the minimal cost boundaries.",
          "properties": {
            "state": "dp[i][j][c] = minimal modification cost for first i items to reach coverage at least j and total payment exactly c under optimal selection of paid items",
            "compression": "due to large c, the DP may compress payment dimensions using the property that only minimal payment for each coverage level matters in the original problem, or employ a branch‑and‑bound with bounding on modification cost."
          },
          "evidence_source": "newly designed algorithm"
        }
      ]
    },
    "difficulty": "hard"
  },
  "algorithmic_delta_claim": {
    "seed_solver_core": "Original DP: iterate items, maintain for each coverage volume j the minimum total payment ar[j]; transition ar[min(j+ti+1, n)] = min(ar[min(j+ti+1, n)], ar[j] + ci); answer is ar[n].",
    "reusable_subroutines": "The original DP can be used as a subroutine to verify that a given modified item set yields minimum payment exactly K (by computing its min payment and comparing to K).",
    "new_solver_core": "A new DP is designed that extends the state to incorporate modification cost. For each item, we iterate over all possible modifications of ti and ci within feasible ranges, and update a multi‑dimensional DP table that records the minimal modification cost to achieve every jointly reachable (coverage, payment) pair. The answer is the minimum modification cost among states that satisfy the target payment K.",
    "new_proof_obligation": "Must prove: (1) the constructed modified instance satisfies the coverage constraint and has min payment equal to K; (2) no modification with strictly smaller total cost can achieve min payment exactly K. The proof relies on the optimal substructure of the extended DP, where each state stores the minimal modification cost for a given (coverage, payment) pair, and a contradiction argument that if a better modification existed it would have been found by the DP.",
