  "applied_helpers": [
    {
      "id": "target_result_binding",
      "selection_reason": "The original problem’s minimal payment naturally becomes the inverse design target. Binding it as the target K is the first essential step.",
      "affected_axes": [
        "C",
        "O"
      ],
      "schema_changes": "Added a new constraint that the modified instance must have minimum payment exactly K; objective changed from minimizing payment to minimizing modification cost while achieving that target.",
      "innovation_reason": "Flips the direction from computing an optimal value to designing input that produces a prescribed optimal value, introducing a constructive feasibility challenge.",
      "difficulty_reason": "Requires the algorithm to handle an external target constraint that couples the traditional DP state with a goal value, forcing search in a larger space."
    },
    {
      "id": "edit_operation_contract",
      "selection_reason": "Concrete modification operations are necessary to define the action space of the inverse design; otherwise the problem would be ill‑defined.",
      "affected_axes": [
        "C",
        "V"
      ],
      "schema_changes": "Introduced a formal definition of allowed edits (changing ti and ci) and their absolute‑difference cost; invariant updated to track how these edits affect coverage and payment within the DP.",
      "innovation_reason": "Formalizes atomic actions on items, turning an open‑ended construction into an enumerable optimization over editing sequences.",
      "difficulty_reason": "The trade‑off between operation cost and target payment creates a multi‑objective optimization that must be proven correct with respect to the original coverage rule."
    },
    {
      "id": "minimality_or_certificate_lock",
      "selection_reason": "Without requiring minimal modification cost, the problem reduces to finding any feasible modification, which is much easier and less interesting.",
      "affected_axes": [
        "O",
        "V"
      ],
      "schema_changes": "Objective set to minimize total modification cost and also output the scheme; invariant asserts that the algorithm’s output is provably minimal among all feasible modifications.",
      "innovation_reason": "Imposes an optimality proof obligation, elevating the problem from mere existence to genuine optimization with a lower bound argument.",
      "difficulty_reason": "The algorithm must not only meet the target constraint but also certify that no cheaper modification exists, which typically requires a DP with optimal substructure and a contradiction proof."
    }
  ],
