          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
        "difficulty_role": "要求算法围绕目标约束反推状态。",
        "prompt_guidance": [
          "目标必须说明要达成的结果性质。",
          "核心约束必须限制目标如何被满足。"
        ],
        "redlines": [
          "不能只是问原答案是否等于给定值。",
          "不能让目标与原核心规律脱节。"
        ]
      },
      {
        "id": "edit_operation_contract",
        "summary": "定义允许修改、构造或参数调整的正式操作集合。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
