        "standard_solution_code": "n = int(input())\nar = [float('inf')] * (n + 1)\nar[0] = 0\nfor i in range(n):\n\t(t, c) = map(int, input().split())\n\tfor j in range(n - 1, -1, -1):\n\t\tw = min(j + t + 1, n)\n\t\tar[w] = min(ar[w], ar[j] + c)\nprint(ar[n])"
      }
