messages.content:
请审查该题面是否兑现规则专属合同。
要求：
- `message` 直接概括结论，不要泛泛而谈。
- `errors` 只写真正构成拒绝的规则专属问题；通过时返回空数组。
- `evidence` 必须引用题面、`new_schema`、规划摘要或规则声明中的具体内容。
- 如果规则声明了 `helpers`，要确认题面把这些 helper 的语义承诺写清，而不是只在规划摘要里出现。
- 如果题面没有把关键语义写清楚，返回 `fail`。

{
  "review_type": "rule_problem_validation",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名反向设计题面审查官，重点确认题面是否写清目标、修改操作和最小性语义。",
  "review_brief": "确认题面是否要求用最少修改或具体设计达成目标，并且修改操作来自原题对象。",
  "rule_under_review": {
    "id": "forward_solution_to_inverse_design",
    "family": "inverse_design",
    "summary": "把正向求解题扩展为给定目标后的最小修改、参数反推或输入设计题。",
    "audit_tags": [
      "single_seed",
      "inverse_problem",
      "minimal_edit"
    ],
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "forward_solution_to_inverse_design",
      "target_shift": "从计算给定输入的结果改成设计输入或修改使目标成立",
      "new_obligation": "定义目标结果、允许修改和最小性证明"
    },
    "helpers": [
      {
        "id": "target_result_binding",
        "summary": "把原题结果绑定成新题要达成的反向目标。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让求解方向从正向计算翻转为目标驱动设计。",
        "difficulty_role": "要求算法围绕目标约束反推状态。",
        "prompt_guidance": [
          "目标必须说明要达成的结果性质。",
          "核心约束必须限制目标如何被满足。"
        ],
        "redlines": [
          "不能只是问原答案是否等于给定值。",
          "不能让目标与原核心规律脱节。"
        ]
      },
      {
        "id": "edit_operation_contract",
        "summary": "定义允许修改、构造或参数调整的正式操作集合。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "把反向设计落实到可枚举或可优化的操作空间。",
        "difficulty_role": "要求证明操作序列与目标结果之间的对应关系。",
        "prompt_guidance": [
          "修改操作必须来自原题对象的自然结构。",
          "不变量要解释修改如何影响目标结果。"
        ],
        "redlines": [
          "不能发明无关操作。",
          "不能让修改只改变叙事外观。"
        ]
      },
      {
        "id": "minimality_or_certificate_lock",
        "summary": "要求输出最小修改代价或可验证设计证据。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让答案承担最小性或构造正确性责任。",
        "difficulty_role": "要求算法证明不能用更少修改达成目标。",
        "prompt_guidance": [
          "输出目标应包含最小代价或具体设计。",
          "不变量要支持下界或正确性证明。"
        ],
        "redlines": [
          "不能只输出任意可行修改。",
          "不能省略最小性证明责任。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "反向目标必须来自原题结果语义",
        "修改操作必须与原核心对象相关",
        "必须承担最小性或设计正确性责任"
      ]
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    },
    "examples": {
      "positive": "给定目标答案，求最少修改几个元素使原性质成立。",
      "negative": "随意添加一种与原题无关的操作来构造任意结果。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题无法定义稳定的反向目标或自然修改操作。",
      "difference_insufficient": "反向设计没有改变主求解方向，只是把原判定换了问法。"
    }
  },
  "plan_context": {
    "mode": "single_seed_extension",
    "applied_rule": "forward_solution_to_inverse_design",
    "objective": {
      "type": "inverse_design_with_target",
      "description": "Minimize the total modification cost under the condition that the modified item set achieves target minimum payment K. Output the minimum modification cost; if impossible, output -1. Additionally, if feasible, output one optimal modification scheme (new values of ti and ci for each item).",
      "target": "optimal_modification_scheme",
      "requires_solution": true
    },
    "difference_plan": {
      "target_distance_band": {
        "min": 0.35,
        "max": 0.6
      },
      "changed_axes": [
        "C",
        "O",
        "V"
      ],
      "same_family_allowed": true,
      "forbidden_reuse": [
        "taco_codeforces_359a62b3c24d",
        "codeforces",
        "Bob came to a cash & carry store, put n items into his trolley, and went to the checkout counter to pay. Each item is described by its price ci and time ti in seconds that a checkout assistant spends on this item. Whi...",
        "不要复写原题的叙事结构、任务定义或样例套路。",
        "不要只替换实体名称后保留同样的输入输出关系。"
      ],
      "rationale": "必须改变核心约束以引入修改操作和目标支付条件；目标从最小化支付转为最小化修改代价并输出方案；不变量从原 DP 最优子结构更新为逆向设计最优性的证明结构。",
      "summary": "从正向求解变为反向设计，需要搜索数据修改空间而非解空间。",
      "mode": "single_seed_extension"
    },
    "algorithmic_delta_claim": {
      "seed_solver_core": "Original DP: iterate items, maintain for each coverage volume j the minimum total payment ar[j]; transition ar[min(j+ti+1, n)] = min(ar[min(j+ti+1, n)], ar[j] + ci); answer is ar[n].",
      "reusable_subroutines": "The original DP can be used as a subroutine to verify that a given modified item set yields minimum payment exactly K (by computing its min payment and comparing to K).",
      "new_solver_core": "A new DP is designed that extends the state to incorporate modification cost. For each item, we iterate over all possible modifications of ti and ci within feasible ranges, and update a multi‑dimensional DP table that records the minimal modification cost to achieve every jointly reachable (coverage, payment) pair. The answer is the minimum modification cost among states that satisfy the target payment K.",
      "new_proof_obligation": "Must prove: (1) the constructed modified instance satisfies the coverage constraint and has min payment equal to K; (2) no modification with strictly smaller total cost can achieve min payment exactly K. The proof relies on the optimal substructure of the extended DP, where each state stores the minimal modification cost for a given (coverage, payment) pair, and a contradiction argument that if a better modification existed it would have been found by the DP.",
      "why_direct_reuse_fails": "The original DP only computes the minimum payment for a fixed input; it cannot search over modifications of the input items. Direct reuse would merely evaluate candidate modifications one by one, leading to an exponential search space without dynamic programming over the modification decisions."
    },
    "shared_core_summary": "",
    "shared_core_anchors": {
      "shared_state": "",
      "shared_transition": "",
      "shared_decision_basis": ""
    },
    "seed_contributions": {
      "seed_a": "",
      "seed_b": ""
    },
    "fusion_ablation": {
      "without_seed_a": "",
      "without_seed_b": ""
    },
    "applied_helpers": [
      {
        "id": "target_result_binding",
        "selection_reason": "The original problem’s minimal payment naturally becomes the inverse design target. Binding it as the target K is the first essential step.",
        "affected_axes": [
          "C",
          "O"
        ],
        "schema_changes": [],
        "innovation_reason": "Flips the direction from computing an optimal value to designing input that produces a prescribed optimal value, introducing a constructive feasibility challenge.",
        "difficulty_reason": "Requires the algorithm to handle an external target constraint that couples the traditional DP state with a goal value, forcing search in a larger space."
      },
      {
        "id": "edit_operation_contract",
        "selection_reason": "Concrete modification operations are necessary to define the action space of the inverse design; otherwise the problem would be ill‑defined.",
        "affected_axes": [
          "C",
          "V"
        ],
        "schema_changes": [],
        "innovation_reason": "Formalizes atomic actions on items, turning an open‑ended construction into an enumerable optimization over editing sequences.",
        "difficulty_reason": "The trade‑off between operation cost and target payment creates a multi‑objective optimization that must be proven correct with respect to the original coverage rule."
      },
      {
        "id": "minimality_or_certificate_lock",
        "selection_reason": "Without requiring minimal modification cost, the problem reduces to finding any feasible modification, which is much easier and less interesting.",
        "affected_axes": [
          "O",
          "V"
        ],
        "schema_changes": [],
        "innovation_reason": "Imposes an optimality proof obligation, elevating the problem from mere existence to genuine optimization with a lower bound argument.",
        "difficulty_reason": "The algorithm must not only meet the target constraint but also certify that no cheaper modification exists, which typically requires a DP with optimal substructure and a contradiction proof."
      }
    ],
    "new_schema": {
      "problem_id": "inv_home_organization_target_cost",
      "source": "derived_from_codeforces_359a62b3c24d_home_organization",
      "input_structure": {
