          {
            "role": "original_items",
            "role_description": "list of items, each given by its space occupation ti and organization cost ci",
            "type": "array",
            "length": {
              "min": 1,
              "max": 2000
            },
            "value_range": {
              "ti": {
                "min": 0,
                "max": 2000
              },
