            },
            "value_range": {
              "min": 1,
              "max": 1000000000
            },
            "properties": {}
          }
        ]
      },
      "core_constraints": {
        "constraints": [
          {
            "name": "original_coverage_after_modifications",
            "description": "After modifications, there must exist a subset P of items so that if you pay to organize them, the total time spent (ti) is at least the number of items you can steal (i.e., n - |P|). Formally, ∑_{i∈P} ti ≥ n - |P|.",
            "formal": "∃ P ⊆ {1..n} : ∑_{i∈P} ti ≥ n - |P|",
            "source_sections": [
              "derived from original problem"
            ]
          },
          {
            "name": "allowed_modifications",
            "description": "For each item i, you may change its space ti to any non‑negative integer and its cost ci to any positive integer. The cost of modifying item i is |new_ti - old_ti| + |new_ci - old_ci|. The total modification cost is the sum over all items.",
            "formal": "Let Δt_i = new_ti - ti, Δc_i = new_ci - ci. Modification cost = ∑_{i=1..n} (|Δt_i| + |Δc_i|). All new_ti ≥ 0, new_ci ≥ 1.",
            "source_sections": [
